# add network information
if network_enabled(self.request):
    user_info["network_nodes"] = self.get_network_user_nodes(user_name)
    user_info["network_routes"] = {"create": schemas.NetworkRemoteUsersAPI.name,
                                   "delete": schemas.NetworkRemoteUserAPI.name}

def get_network_user_nodes(self, user_name):
    try:
        path = schemas.NetworkNodesAPI.path
        resp = request_api(self.request, path, "GET")
        check_response(resp)
        network_nodes = get_json(resp)["nodes"]
    except HTTPNotFound:
        network_nodes = []

    try:
        path = schemas.NetworkRemoteUsersAPI.path
        resp = request_api(self.request, path, "GET")
        check_response(resp)
        network_remote_users = get_json(resp)["remote_users"]
    except HTTPNotFound:
        network_remote_users = []

    existing_network_remote_user_nodes = {
        remote_user["node_name"]: remote_user["remote_user_name"]
        for remote_user in network_remote_users
        if remote_user["user_name"] == user_name
    }
    return [(node["name"], existing_network_remote_user_nodes.get(node["name"])) for node in network_nodes]
